    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // The base score is already post_residual. We add weight to avoid large residuals.
    score += (post_residual as f64) * 0.5;

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward it.
    // This minimizes the gap left for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 20.0 * (100.0 / (1.0 + diff));
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is very low, suggesting we are forced to open one.
    if bin_residual == bin_capacity {
        score += 35.0; 
        if fitting_bins_count == 0 {
            score -= 40.0; // Forced to open new bin
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current mean state.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.2;

    // 5. Progression Weight:
    // As we approach the end of the stream, prioritize space density over lookahead.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
